import { type Rule, type RuleMessages, type RuleMeta } from "stylelint";
import { type Syntax } from "../../syntaxes/index.ts";
import type { RuleCheck } from "../ruleCheck/index.ts";
/** What the namespace hands a rule: its name, its messages closing with that name, and the syntax. */
export type RuleScope<M extends RuleMessages> = {
    ruleName: string;
    messages: M;
    syntax: Syntax;
};
/** What a rule module defines once, whichever namespaces it is registered under. `defersToRunEnd` marks a rule that reads what a run's writers leave, so it checks last, behind the lineness-deferred rules: `indentation`, which reads every line, and `declaration-block-single-line-max-declarations`, which reads a block's lineness and breaks the block behind them. `checksAheadOfLineness` has such a rule check at the head of the lineness tier as well, so the tier reads the breaks it writes. */
export type RuleDefinition<P, S, M extends RuleMessages> = {
    shortName: string;
    meta: RuleMeta;
    messages: M;
    rule: (scope: RuleScope<M>, primary: P, secondaryOptions: S) => RuleCheck;
    defersToRunEnd?: true;
    checksAheadOfLineness?: true;
};
/**
 * Names a rule's messages before a rule name closes them under each namespace.
 * @param messages - Each message by key.
 * @returns The same messages, typed as written.
 */
export declare function defineMessages<M extends RuleMessages>(messages: M): M;
/** What `defineRule` returns: the rule under a syntax's namespace, with the options its function is written for in the type arguments, where `defineStylistic` reads them. */
export type RuleFactory<P, S, M extends RuleMessages> = (syntax: Syntax) => Rule<P, S, M>;
/**
 * Turns a rule definition into a factory over a syntax, which names the rule under the syntax's namespace, closes the messages with that name, and refuses a root the syntax does not accept in front of the rule: with one warning naming the namespaces that would read it, or without a word where a configured copy of the rule under one of them does.
 * @param definition - The rule's definition.
 * @returns The factory, whose result `createPlugin` takes.
 */
export declare function defineRule<P, S, M extends RuleMessages>(definition: RuleDefinition<P, S, M>): RuleFactory<P, S, M>;
